def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    if not b:
        return sorted(a)

    # Merge overlapping intervals in both a and b
    def merge_intervals(intervals):
        if not intervals:
            return []

        intervals = sorted(intervals)
        merged = [intervals[0]]

        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching, merge them
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)

        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    result = []

    for a_interval in a_merged:
        # Start with the full a_interval
        current_intervals = [a_interval]

        # Subtract each b_interval from current_intervals
        for b_interval in b_merged:
            next_intervals = []
            for curr in current_intervals:
                # curr is [start, end)
                # b_interval is [b_start, b_end)

                if b_interval[1] <= curr[0] or b_interval[0] >= curr[1]:
                    # No overlap
                    next_intervals.append(curr)
                else:
                    # There is overlap
                    # Keep the part before b_interval
                    if curr[0] < b_interval[0]:
                        next_intervals.append([curr[0], b_interval[0]])
                    # Keep the part after b_interval
                    if curr[1] > b_interval[1]:
                        next_intervals.append([b_interval[1], curr[1]])

            current_intervals = next_intervals

        result.extend(current_intervals)

    # Merge result intervals (in case they became adjacent after subtraction)
    result = merge_intervals(result)

    return result

